/* Saved HTML stays in the browser. The inert template is never inserted or executed. */
function readSavedInstagramPage(base,source){
 if(source.length>8*1024*1024)throw Error('La página guardada supera los 8 MB.');
 const template=document.createElement('template');template.innerHTML=source;const root=template.content;
 const canonical=root.querySelector('meta[property="og:url"]')?.getAttribute('content')||root.querySelector('link[rel="canonical"]')?.getAttribute('href');
 if(!canonical||InstagramImportModel.username(canonical)!==base.profile.handle)throw Error('El HTML no corresponde al perfil que estás importando. Guardá la página de ese perfil, no la de inicio ni una publicación.');
 let details;try{details=InstagramImportModel.parse(base.profile.handle,source)}catch{details={profile:{handle:base.profile.handle,highlights:[]},availability:{bio:false,highlights:'unavailable'}}}
 const profile=details.profile,header=root.querySelector('main header')||root.querySelector('header'),main=root.querySelector('main')||root;
 const text=element=>{if(!element)return '';const copy=element.cloneNode(true);copy.querySelectorAll('script,style,[hidden],[aria-hidden="true"]').forEach(n=>n.remove());copy.querySelectorAll('br').forEach(br=>br.replaceWith(document.createTextNode('\n')));return (copy.textContent||'').replace(/\u00a0/g,' ').trim()};
 const count=element=>{if(!element)return null;const titled=[element,...element.querySelectorAll('[title],[data-count]')].map(el=>el.getAttribute('data-count')||el.getAttribute('title')).find(v=>v&&/^\d+(?:[.,\s]\d{3})*$/.test(v.trim()));if(titled)return titled.trim();return text(element).match(/\d[\d.,]*(?:\s*(?:mil|millones|[KM]))?/i)?.[0]||null};
 const anchors=[...(header||main).querySelectorAll('a[href]')];
 for(const [key,suffix]of [['followers','followers'],['following','following']]){const match=anchors.find(a=>{try{const u=new URL(a.getAttribute('href'),'https://www.instagram.com/');return ['www.instagram.com','instagram.com'].includes(u.hostname)&&u.pathname.replace(/\/$/,'')==='/'+base.profile.handle+'/'+suffix}catch{return false}})||anchors.find(a=>new RegExp(key==='followers'?'\\b(followers|seguidores)\\b':'\\b(following|seguidos|siguiendo)\\b','i').test(text(a))),value=count(match);if(value!==null)profile[key]=value}
 const posts=[...(header?.querySelectorAll('li')||[])].find(el=>/\b(posts|publicaciones|publicaç[õo]es)\b/i.test(text(el)))||[...(header||main).querySelectorAll('span,div')].find(el=>/^\d[\d.,\s]*(?:[KM]|mil)?\s*(posts|publicaciones|publicaç[õo]es)$/i.test(text(el)));if(posts){const value=count(posts);if(value!==null)profile.posts=value}
 const explicitBio=(header||main).querySelector('[data-testid="profile-bio"],[data-profile-bio]');
 if(explicitBio){profile.bio=text(explicitBio).slice(0,2200);details.availability.bio=true}
 else if(header&&!Array.from(header.querySelectorAll('button,[role="button"]')).some(el=>/^(más|more|mais)$/i.test(text(el)))){const named=[...header.querySelectorAll('span,strong,h1')].find(el=>text(el)===base.profile.name&&!el.querySelector('span,strong,h1'));let region=named?.parentElement||header;for(let i=0;i<8&&region;i++,region=region===header?null:region.parentElement){const candidates=[...region.querySelectorAll('span[dir="auto"]')].filter(el=>!el.closest('a,button')&&el.querySelector('br')&&text(el)!==base.profile.name),unique=[...new Set(candidates.map(text))];if(unique.length===1){profile.bio=unique[0].slice(0,2200);details.availability.bio=true;break}}}

 function media(img){if(!img)return null;const options=[img.getAttribute('src'),img.getAttribute('data-src'),...(img.getAttribute('srcset')||'').split(/,\s*(?=https?:)/).reverse().map(s=>s.replace(/\s+\d+(?:\.\d+)?[wx]$/,''))];return options.map(InstagramImportModel.imageURL).find(Boolean)||null}
 const avatar=(header||main).querySelector('img[alt*="'+base.profile.handle+'"]');if(avatar&&media(avatar))profile.avatar=media(avatar);
 const highlights=[];for(const anchor of main.querySelectorAll('a[href]')){let url;try{url=new URL(anchor.getAttribute('href'),'https://www.instagram.com/')}catch{continue}const match=url.pathname.match(/^\/stories\/highlights\/(\d+)\/?$/);if(url.protocol!=='https:'||!['www.instagram.com','instagram.com'].includes(url.hostname)||!match||highlights.some(h=>h.id===match[1]))continue;const label=(text(anchor)||anchor.getAttribute('title')||'').slice(0,80);highlights.push({id:match[1],label,cover:media(anchor.querySelector('img')),stories:[]});if(highlights.length===50)break}
 if(highlights.length){const known=new Map((profile.highlights||[]).map(h=>[h.id,h]));profile.highlights=highlights.map(h=>({...h,cover:h.cover||known.get(h.id)?.cover||null,stories:known.get(h.id)?.stories||[]}));details.availability.highlights='available'}
 const merged={...base,profile:{...base.profile},availability:{...base.availability},source:'saved-page'};
 for(const field of ['name','avatar','link','category','pronouns'])if(profile[field])merged.profile[field]=profile[field];
 for(const field of ['posts','followers','following'])if(profile[field]&&profile[field]!=='—'){const old=base.profile[field];merged.profile[field]=/[km]|millones/i.test(profile[field])&&old&&old!=='—'&&!/[km]|millones/i.test(old)?old:profile[field]}
 if(details.availability.bio){merged.profile.bio=profile.bio;merged.availability.bio=true}
 if(details.availability.highlights==='available'){const old=new Map((base.profile.highlights||[]).map(h=>[h.id,h]));merged.profile.highlights=(profile.highlights||[]).map(h=>({...h,cover:h.cover||old.get(h.id)?.cover||null,stories:h.stories?.length?h.stories:old.get(h.id)?.stories||[]}));merged.availability.highlights='available'}
 if(!base.posts.length&&details.posts?.length){merged.posts=details.posts;merged.photos=details.photos;merged.truncated=details.truncated}merged.warnings=InstagramImportModel.warningsFor(merged);if((merged.profile.highlights||[]).some(h=>!h.cover))merged.warnings.push('Algunas portadas no conservan su enlace original. Podés cambiarlas tocando sus círculos.');return merged;
}
